import { describe, expect, it } from "vitest";
import { lateFeeCents } from "../src/fees.js";

const loan = { id: 1, bookId: 1, member: "ada", loanDate: "2026-10-01", dueDate: "2026-10-15", renewed: false };

describe("lateFeeCents", () => {
  it("charges nothing when returned early", () => {
    expect(lateFeeCents({ ...loan, returnDate: "2026-10-10" }, "2026-11-01")).toBe(0);
  });

  it("charges nothing when returned the day before the due date", () => {
    expect(lateFeeCents({ ...loan, returnDate: "2026-10-14" }, "2026-11-01")).toBe(0);
  });

  it("charges nothing for an open loan that is not due yet", () => {
    expect(lateFeeCents({ ...loan, returnDate: null }, "2026-10-05")).toBe(0);
  });
});
